*** Begin Patch
*** Add File: slides/slide-02.js
+const pptxgen = require('pptxgenjs');
+
+const slideConfig = {
+  type: 'content',
+  index: 2,
+  title: '84% of Developers Are Working, but Full-Time Employment Dips in the U.S.',
+};
+
+function addPageBadge(slide, theme, pageNum) {
+  slide.addShape(pptxgen.ShapeType.roundRect, {
+    x: 9.25,
+    y: 5.05,
+    w: 0.55,
+    h: 0.35,
+    fill: { color: theme.primary },
+    line: { color: theme.primary },
+    radius: 0.12,
+  });
+  slide.addText(String(pageNum), {
+    x: 9.25,
+    y: 5.07,
+    w: 0.55,
+    h: 0.3,
+    align: 'center',
+    fontFace: 'Calibri',
+    fontSize: 12,
+    color: theme.bg,
+  });
+}
+
+function createSlide(pres, theme) {
+  const slide = pres.addSlide();
+  slide.background = { color: theme.bg };
+
+  // Header
+  slide.addText('Employment Status', {
+    x: 0.6,
+    y: 0.35,
+    w: 8.6,
+    h: 0.35,
+    fontFace: 'Georgia',
+    fontSize: 16,
+    color: theme.accent,
+  });
+  slide.addText(slideConfig.title, {
+    x: 0.6,
+    y: 0.7,
+    w: 9.2,
+    h: 0.7,
+    fontFace: 'Georgia',
+    fontSize: 28,
+    bold: true,
+    color: theme.primary,
+  });
+
+  // Key callouts
+  slide.addShape(pptxgen.ShapeType.roundRect, {
+    x: 0.6,
+    y: 1.55,
+    w: 4.5,
+    h: 0.85,
+    fill: { color: theme.light, transparency: 20 },
+    line: { color: theme.light },
+    radius: 0.18,
+  });
+  slide.addText('84% of respondents are currently working', {
+    x: 0.85,
+    y: 1.72,
+    w: 4.1,
+    h: 0.5,
+    fontFace: 'Calibri',
+    fontSize: 18,
+    color: theme.primary,
+  });
+
+  slide.addShape(pptxgen.ShapeType.roundRect, {
+    x: 5.35,
+    y: 1.55,
+    w: 4.45,
+    h: 0.85,
+    fill: { color: theme.accent, transparency: 18 },
+    line: { color: theme.accent },
+    radius: 0.18,
+  });
+  slide.addText('U.S. full-time: 69% (2023) → 64.8% (2024)', {
+    x: 5.6,
+    y: 1.72,
+    w: 4.0,
+    h: 0.5,
+    fontFace: 'Calibri',
+    fontSize: 18,
+    color: theme.primary,
+  });
+
+  // Chart area
+  const chartX = 0.6;
+  const chartY = 2.55;
+  const chartW = 9.2;
+  const chartH = 2.2;
+
+  slide.addShape(pptxgen.ShapeType.roundRect, {
+    x: chartX,
+    y: chartY,
+    w: chartW,
+    h: chartH,
+    fill: { color: 'edf2f4' },
+    line: { color: theme.light, transparency: 40 },
+    radius: 0.18,
+  });
+
+  // Grouped bars (simple, data-forward)
+  // Categories: Full-time, Freelance/Contract, Student
+  const categories = [
+    { label: 'Full-time', global: 69.0, us: 64.8 },
+    { label: 'Freelance', global: 16.4, us: null },
+    { label: 'Student', global: 13.2, us: null },
+  ];
+
+  // Chart geometry
+  const leftPad = 1.3;
+  const rightPad = 0.6;
+  const topPad = 0.55;
+  const bottomPad = 0.45;
+  const axisX = chartX + leftPad;
+  const axisYTop = chartY + topPad;
+  const axisYBottom = chartY + chartH - bottomPad;
+  const axisW = chartW - leftPad - rightPad;
+  const axisH = axisYBottom - axisYTop;
+
+  // x-axis and y-axis
+  slide.addShape(pptxgen.ShapeType.line, {
+    x: axisX,
+    y: axisYBottom,
+    w: axisW,
+    h: 0,
+    line: { color: theme.secondary, transparency: 55, width: 1 },
+  });
+  slide.addShape(pptxgen.ShapeType.line, {
+    x: axisX,
+    y: axisYTop,
+    w: 0,
+    h: axisH,
+    line: { color: theme.secondary, transparency: 55, width: 1 },
+  });
+
+  // y ticks: 0, 20, 40, 60, 80
+  const maxY = 80;
+  [0, 20, 40, 60, 80].forEach((t) => {
+    const y = axisYBottom - (t / maxY) * axisH;
+    slide.addShape(pptxgen.ShapeType.line, {
+      x: axisX,
+      y,
+      w: axisW,
+      h: 0,
+      line: { color: theme.secondary, transparency: 85, width: 1 },
+    });
+    slide.addText(`${t}%`, {
+      x: chartX + 0.65,
+      y: y - 0.12,
+      w: 0.55,
+      h: 0.25,
+      fontFace: 'Calibri',
+      fontSize: 10,
+      color: theme.secondary,
+      align: 'right',
+    });
+  });
+
+  const groupCount = categories.length;
+  const groupGap = 0.55;
+  const groupW = (axisW - groupGap * (groupCount - 1)) / groupCount;
+  const barGap = 0.12;
+  const barW = (groupW - barGap) / 2;
+  const barMaxH = axisH;
+
+  categories.forEach((c, i) => {
+    const gx = axisX + i * (groupW + groupGap);
+
+    // Global bar
+    const globalH = (c.global / maxY) * barMaxH;
+    slide.addShape(pptxgen.ShapeType.rect, {
+      x: gx,
+      y: axisYBottom - globalH,
+      w: barW,
+      h: globalH,
+      fill: { color: theme.primary },
+      line: { color: theme.primary },
+    });
+    slide.addText(`${c.global.toFixed(1)}%`, {
+      x: gx,
+      y: axisYBottom - globalH - 0.22,
+      w: barW,
+      h: 0.2,
+      fontFace: 'Calibri',
+      fontSize: 10,
+      color: theme.primary,
+      align: 'center',
+    });
+
+    // U.S. bar (only for full-time)
+    if (c.us !== null) {
+      const usH = (c.us / maxY) * barMaxH;
+      slide.addShape(pptxgen.ShapeType.rect, {
+        x: gx + barW + barGap,
+        y: axisYBottom - usH,
+        w: barW,
+        h: usH,
+        fill: { color: theme.accent },
+        line: { color: theme.accent },
+      });
+      slide.addText(`${c.us.toFixed(1)}%`, {
+        x: gx + barW + barGap,
+        y: axisYBottom - usH - 0.22,
+        w: barW,
+        h: 0.2,
+        fontFace: 'Calibri',
+        fontSize: 10,
+        color: theme.primary,
+        align: 'center',
+      });
+    }
+
+    slide.addText(c.label, {
+      x: gx - 0.05,
+      y: axisYBottom + 0.08,
+      w: groupW + 0.1,
+      h: 0.25,
+      fontFace: 'Calibri',
+      fontSize: 11,
+      color: theme.secondary,
+      align: 'center',
+    });
+  });
+
+  // Legend
+  slide.addShape(pptxgen.ShapeType.rect, {
+    x: 0.75,
+    y: 4.9,
+    w: 0.18,
+    h: 0.12,
+    fill: { color: theme.primary },
+    line: { color: theme.primary },
+  });
+  slide.addText('Global', {
+    x: 0.98,
+    y: 4.84,
+    w: 1.0,
+    h: 0.25,
+    fontFace: 'Calibri',
+    fontSize: 11,
+    color: theme.secondary,
+  });
+
+  slide.addShape(pptxgen.ShapeType.rect, {
+    x: 1.85,
+    y: 4.9,
+    w: 0.18,
+    h: 0.12,
+    fill: { color: theme.accent },
+    line: { color: theme.accent },
+  });
+  slide.addText('United States (full-time)', {
+    x: 2.08,
+    y: 4.84,
+    w: 2.5,
+    h: 0.25,
+    fontFace: 'Calibri',
+    fontSize: 11,
+    color: theme.secondary,
+  });
+
+  slide.addText(
+    'Notes: Global status breakdown — full-time 69%, independent contracting/freelancing 16.4%, full-time students 13.2%.',
+    {
+      x: 0.6,
+      y: 5.18,
+      w: 8.5,
+      h: 0.35,
+      fontFace: 'Calibri',
+      fontSize: 10,
+      color: theme.secondary,
+    }
+  );
+
+  addPageBadge(slide, theme, 2);
+  return slide;
+}
+
+if (require.main === module) {
+  const pres = new pptxgen();
+  pres.layout = 'LAYOUT_16x9';
+  const theme = {
+    primary: '22223b',
+    secondary: '4a4e69',
+    accent: '9a8c98',
+    light: 'c9ada7',
+    bg: 'f2e9e4',
+  };
+  createSlide(pres, theme);
+  pres.writeFile({ fileName: 'slide-02-preview.pptx' });
+}
+
+module.exports = { createSlide, slideConfig };
+
*** End Patch
PATCH

