+  slide.addShape(pptxgen.ShapeType.rect, {
+    x: 0,
+    y: 0,
+    w: 10,
+    h: 1.0,
+    fill: { color: theme.primary },
+    line: { color: theme.primary },
+  });
+  slide.addText(slideConfig.title, {
+    x: 0.6,
+    y: 0.25,
+    w: 8.9,
+    h: 0.6,
+    fontFace: 'Georgia',
+    fontSize: 26,
+    bold: true,
+    color: theme.bg,
+  });
+
+  // Cards
+  const cards = [
+    {
+      title: 'Plan for a more flexible workforce mix',
+      body:
+        'U.S. full-time employment fell from 69% (2023) to 64.8% (2024).\nFreelancing remains significant at 16.4% globally.',
+    },
+    {
+      title: 'Hybrid is still the baseline',
+      body:
+        'Hybrid stays at 42% (most common).\nIn-person rose from 15% (2022) to 20% (2024).',
+    },
+    {
+      title: 'Pay premiums concentrate in DevRel, leadership, SRE',
+      body:
+        'Senior Executive ($127,388), Dev Advocate ($124,203), Manager ($115,999).\nHighest-paid technical roles: SRE ($99,099) and Cloud Infra. Engineer ($96,666).',
+    },
+    {
+      title: 'Language choice correlates with pay',
+      body:
+        'Top: Erlang (~$97K), Clojure (~$95K), Elixir (~$93K).\nLower: Dart (~$44K), Prolog (~$43K), PHP (~$49K).',
+    },
+    {
+      title: 'Engage developers in tooling decisions',
+      body:
+        '62% influence technology purchases and 60% prefer build-and-buy.\nTop evaluation methods: free trials (75%) and asking other developers (73%).',
+    },
+  ];
+
+  const startX = 0.6;
+  const startY = 1.3;
+  const colW = 4.65;
+  const rowH = 1.25;
+  const gapY = 0.25;
+  const gapX = 0.5;
+
+  cards.forEach((c, idx) => {
+    const col = idx % 2;
+    const row = Math.floor(idx / 2);
+    const x = startX + col * (colW + gapX);
+    const y = startY + row * (rowH + gapY);
+    const h = idx === 4 ? 1.45 : rowH;
+    slide.addShape(pptxgen.ShapeType.roundRect, {
+      x,
+      y,
+      w: colW,
+      h,
+      fill: { color: 'edf2f4' },
+      line: { color: theme.light, transparency: 35 },
+      radius: 0.18,
+    });
+    slide.addText(c.title, {
