+      y: y + 0.18,
+      w: colW - 0.5,
+      h: 0.35,
+      fontFace: 'Georgia',
+      fontSize: 14,
+      bold: true,
+      color: theme.primary,
+    });
+    slide.addText(c.body, {
+      x: x + 0.25,
+      y: y + 0.55,
+      w: colW - 0.5,
+      h: h - 0.65,
+      fontFace: 'Calibri',
+      fontSize: 12,
+      color: theme.secondary,
+      lineSpacingMultiple: 1.1,
+    });
+  });
+
+  slide.addText('Source: Stack Overflow Developer Survey 2024 (Work & Compensation).', {
+    x: 0.6,
+    y: 5.18,
+    w: 8.8,
+    h: 0.35,
+    fontFace: 'Calibri',
+    fontSize: 10,
+    color: theme.secondary,
+  });
+
+  addPageBadge(slide, theme, 8);
+  return slide;
+}
+
+if (require.main === module) {
