+    { name: 'Full-stack', exp: 10, salary: 63333 },
+    { name: 'Blockchain', exp: 9, salary: 85925 },
+    { name: 'Front-end', exp: 8, salary: 48787 },
+    { name: 'Student', exp: 2, salary: 15466 },
+  ];
+
