+    radius: 0.18,
+  });
+
+  const leftPad = 0.75;
+  const bottomPad = 0.6;
+  const topPad = 0.35;
+  const rightPad = 0.35;
+  const axisX = plotX + leftPad;
+  const axisYTop = plotY + topPad;
+  const axisYBottom = plotY + plotH - bottomPad;
+  const axisW = plotW - leftPad - rightPad;
+  const axisH = axisYBottom - axisYTop;
+
+  slide.addShape(shapes.LINE, {
+    x: axisX,
